/* ===== V10.40 (F11) : ACADÉMIE, PARTIE 9 — CALCULS DU PILOTE DE LIGNE =====
   Pour chaque formule : un cours concis et complet, 3 exemples corrigés, 10 questions du plus facile au plus difficile avec leurs corrigés,
   et les documents de vol qu'elle sert à remplir (boutons qui ouvrent le document). Dernier module : cas complet Paris → La Réunion en A350.
   Contenu GÉNÉRÉ par tools/gen_calcpro.py : chaque réponse est calculée par la formule du module [CALCULÉ].
   Règles : EASA Part-CAT (CAT.OP.MPA.181 carburant, CAT.OP.MPA.281 minimum fuel, CAT.POL.A.230 / 235 atterrissage, CAT.POL.MAB.100 masses),
   ORO.FTL (temps de service), atmosphère type OACI (Doc 7488). Les données de l'exploitant et du constructeur font foi. */
(function(){
if(!window.ACAD||!ACAD.setPart) return;
const css=document.createElement('style'); css.textContent=`.lf{background:#0b1622;border-left:3px solid #3fd0ff;padding:6px 10px;margin:6px 0;font:600 13px/1.6 'JetBrains Mono',monospace}
.lx{background:#13201a;border-left:3px solid #4ade80;padding:6px 10px;margin:8px 0} .ld{margin:10px 0;padding:8px;border:1px dashed #2b3d50;border-radius:8px} .ld button{margin:3px 4px 0 0}`;
document.head.appendChild(css);
const MODS=[{"id": "L1", "t": "Formule 1 — Unités et conversions", "h": "<p>Un pilote de ligne manipule chaque jour des <b>milles nautiques</b>, des <b>pieds</b>, des <b>nœuds</b>, des <b>kilogrammes</b> (parfois des livres), des <b>litres</b> de carburant et des <b>hectopascals</b> (parfois des inHg). Toute conversion se fait avec un facteur, et toute erreur d'unité est une erreur de sécurité.</p><div class=\"lf\">1 NM = 1 852 m · 1 ft = 0,3048 m (1 m = 3,281 ft) · 1 kt = 1,852 km/h · 1 kg = 2,205 lb · 1 inHg = 33,864 hPa<br>masse carburant (kg) = volume (l) × masse volumique (kg/l) · JET A-1 ≈ 0,775 à 0,84 kg/l selon la température · °F = °C × 9/5 + 32 · K = °C + 273,15</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>Avitaillement : il faut 15 000 kg. Masse volumique annoncée 0,80 kg/l. Volume = 15 000 / 0,80 = <b>18 750 l</b>.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Une STAR impose 9 000 ft : 9 000 × 0,3048 = <b>2 743 m</b>.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Vérification après avitaillement : jauges 4 200 kg → 19 300 kg, bon 19 000 l à 0,795 : bon = 15 105 kg, jauges = 15 100 kg : écart de 5 kg, cohérent.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"fuel\">Bilan carburant</button> <button type=\"button\" class=\"mini\" data-docopen=\"loadsheet\">Devis de masse et centrage</button></div>", "quiz": [{"q": "1 NM vaut :", "o": ["1 852 m", "1 609 m", "1 000 m", "6 076 m"], "c": 0, "why": "1 mille nautique = 1 852 m (une minute d'arc de latitude)."}, {"q": "3 000 m en pieds (1 m = 3,281 ft) :", "o": ["914 ft", "984 ft", "30 000 ft", "9 843 ft"], "c": 3, "why": "3 000 × 3,281 = 9 843 ft."}, {"q": "20 000 kg en livres (1 kg = 2,205 lb) :", "o": ["9 070 lb", "20 000 lb", "44 100 lb", "9 072 lb"], "c": 2, "why": "20 000 × 2,205 = 44 100 lb. Diviser au lieu de multiplier est l'erreur classique."}, {"q": "450 kt en km/h :", "o": ["243 km/h", "833 km/h", "724 km/h", "450 km/h"], "c": 1, "why": "450 × 1,852 = 833 km/h."}, {"q": "10 000 l de JET A-1 à 0,80 kg/l pèsent :", "o": ["8 000 kg", "12 500 kg", "10 000 kg", "800 kg"], "c": 0, "why": "10 000 × 0,80 = 8 000 kg."}, {"q": "On doit embarquer 18 000 kg de JET A-1 à 0,79 kg/l. Volume à commander ?", "o": ["14 220 l", "18 000 l", "22,8 l", "22 785 l"], "c": 3, "why": "Volume = masse / masse volumique = 18 000 / 0,79 = 22 785 l."}, {"q": "29,92 inHg en hPa (1 inHg = 33,864 hPa) :", "o": ["1 000,0 hPa", "883,5 hPa", "1 013,2 hPa", "992,0 hPa"], "c": 2, "why": "29,92 × 33,864 = 1 013,2 hPa : la pression standard."}, {"q": "−40 °C en °F (°F = °C × 9/5 + 32) :", "o": ["−8 °F", "−40 °F", "−72 °F", "0 °F"], "c": 1, "why": "−40 × 1,8 + 32 = −40 : les deux échelles se croisent à −40."}, {"q": "Le camion annonce 22 000 l avitaillés à 0,80 kg/l, mais l'équipage avait demandé 22 000 kg. Combien de kg manquent ?", "o": ["4 400 kg", "0 kg", "5 500 kg", "2 200 kg"], "c": 0, "why": "22 000 l × 0,80 = 17 600 kg reçus ; il manque 4 400 kg. Vérification croisée bon d'avitaillement / jauges : erreur d'unité de l'accident de 1983 (Air Canada 143)."}, {"q": "Jauges : 9 500 kg avant avitaillement, 21 400 kg après ; bon : 15 100 l à 0,79 kg/l. Écart entre jauges et bon ?", "o": ["0 kg", "3 200 kg", "−180 kg", "29 kg"], "c": 3, "why": "Avitaillé selon le bon : 15 100 × 0,79 = 11 929 kg ; selon les jauges : 21 400 − 9 500 = 11 900 kg ; écart 29 kg, à comparer à la tolérance de l'exploitant."}]}, {"id": "L2", "t": "Formule 2 — Atmosphère type (ISA) et altimétrie", "h": "<p>L'atmosphère réelle se compare à l'<b>atmosphère type OACI (ISA)</b>. L'écart ISA change les performances (moteurs, portance) et les altitudes vraies.</p><div class=\"lf\">T<sub>ISA</sub>(°C) = 15 − 1,98 × h(ft)/1 000 (jusqu'à 36 089 ft, puis −56,5 °C) · écart ISA = T réelle − T<sub>ISA</sub><br>altitude-pression ≈ altitude + (1 013 − QNH) × 28 ft · altitude-densité ≈ altitude-pression + 120 × écart ISA<br>correction de froid ≈ hauteur × 4 % par 10 °C sous ISA (règle empirique ; tables OACI PANS-OPS pour l'exploitation)</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>FL370, −50 °C : ISA = −56,5 °C → écart <b>ISA +6,5</b> : poussée disponible et plafond un peu plus bas.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Aérodrome 2 000 ft, QNH 1 023 : altitude-pression = 2 000 − 280 = <b>1 720 ft</b>.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Même terrain à 35 °C : ISA à 1 720 ft ≈ 11,6 °C, écart ≈ +23 °C ; altitude-densité ≈ 1 720 + 2 800 = <b>≈ 4 500 ft</b> : distances de décollage nettement plus longues.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"metar\">METAR / TAF</button> <button type=\"button\" class=\"mini\" data-docopen=\"perf\">Performances (TODC)</button> <button type=\"button\" class=\"mini\" data-docopen=\"wintem\">Vents et températures</button></div>", "quiz": [{"q": "Température ISA au niveau de la mer :", "o": ["0 °C", "20 °C", "15 °C", "−56,5 °C"], "c": 2, "why": "Atmosphère type OACI : 15 °C et 1 013,25 hPa au niveau de la mer."}, {"q": "Décroissance de la température ISA dans la troposphère :", "o": ["≈ 1 °C par 1 000 ft", "≈ 2 °C par 1 000 ft", "≈ 6,5 °C par 1 000 ft", "≈ 3 °C par 100 ft"], "c": 1, "why": "1,98 °C par 1 000 ft (6,5 °C par km) jusqu'à la tropopause."}, {"q": "Température ISA au FL100 :", "o": ["−4,8 °C", "−5,0 °C", "5,0 °C", "−50,0 °C"], "c": 0, "why": "15 − 1,98 × 10 = −4,8 °C."}, {"q": "Température ISA au FL390 :", "o": ["−62,2 °C", "−45,0 °C", "−65,0 °C", "−56,5 °C"], "c": 3, "why": "Au-dessus de la tropopause (36 089 ft en ISA), la température reste à −56,5 °C."}, {"q": "Au FL350, on relève −45 °C. Écart ISA ?", "o": ["ISA −9", "ISA +0", "ISA +9", "ISA +45"], "c": 2, "why": "ISA au FL350 = −54,3 °C ; écart = −45 − (−54,3) ≈ +9 °C."}, {"q": "Aérodrome à 1 200 ft, QNH 998 hPa (1 hPa ≈ 28 ft). Altitude-pression ?", "o": ["780 ft", "1 620 ft", "1 200 ft", "1 350 ft"], "c": 1, "why": "(1 013 − 998) × 28 = 420 ft ; 1 200 + 420 = 1 620 ft. Pression basse : l'altitude-pression est plus haute que l'altitude."}, {"q": "Même aérodrome (altitude-pression 1 620 ft), température 30 °C. Altitude-densité (≈ 120 ft par °C d'écart ISA) ?", "o": ["≈ 3 800 ft", "≈ 1 620 ft", "≈ 5 220 ft", "≈ −560 ft"], "c": 0, "why": "ISA à 1 620 ft = 11,8 °C ; écart = 18,2 °C ; altitude-densité ≈ 1 620 + 120 × 18,2 ≈ 3 800 ft : l'avion décolle comme s'il était à cette altitude."}, {"q": "Altimètre calé au QFE, à l'atterrissage, il indique :", "o": ["L'altitude du terrain", "Le niveau de vol", "1 013 ft", "0 ft (la hauteur)"], "c": 3, "why": "QFE = pression au seuil : l'altimètre donne la hauteur au-dessus du terrain."}, {"q": "En croisière à basse altitude, on oublie de passer du 1013 au QNH 993 en descente. L'avion est en réalité :", "o": ["≈ 560 ft plus haut qu'indiqué", "À l'altitude indiquée", "≈ 560 ft plus bas qu'indiqué", "≈ 20 ft plus bas"], "c": 2, "why": "Calage trop fort de 20 hPa : l'altimètre surestime de 20 × 28 ≈ 560 ft. « Des hautes vers les basses pressions : attention en bas »."}, {"q": "Aérodrome au niveau de la mer, −15 °C au sol (ISA −30). Hauteur minimale à respecter : 3 000 ft. Correction de froid (≈ 4 % de la hauteur par 10 °C sous ISA) ?", "o": ["≈ +120 ft", "≈ +360 ft", "≈ −360 ft", "Aucune"], "c": 1, "why": "3 000 × 4 % × 3 = 360 ft à ajouter : par grand froid, l'avion est plus bas que ce qu'indique son altimètre."}]}, {"id": "L3", "t": "Formule 3 — Vitesses : CAS, TAS, Mach, vitesse sol", "h": "<p><b>CAS</b> : vitesse lue (corrigée), qui fixe la portance et les limites structurales. <b>TAS</b> : vitesse par rapport à l'air. <b>Mach</b> : TAS divisée par la vitesse du son, qui ne dépend que de la température. <b>GS</b> : TAS combinée au vent.</p><div class=\"lf\">a (kt) = 38,94 × √T(K) · M = TAS / a · TAS ≈ CAS × (1 + 0,02 × h/1 000) sous FL100 (règle) · GS = TAS ± composante de vent</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>FL330, −51 °C : a = 38,94 × √222,15 = 580 kt ; à Mach 0,78 → TAS = <b>452 kt</b>.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Vent de face 40 kt → GS = 412 kt ; 1 000 NM en <b>2 h 26</b>.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Approche : 160 kt CAS à 3 000 ft → TAS ≈ 160 × 1,06 = <b>170 kt</b>.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"ofp\">OFP / log de navigation</button> <button type=\"button\" class=\"mini\" data-docopen=\"wintem\">Vents et températures</button></div>", "quiz": [{"q": "Vitesse du son en ISA au niveau de la mer (a = 38,94 √T(K)) :", "o": ["661 kt", "340 kt", "1 224 kt", "573 kt"], "c": 0, "why": "38,94 × √288,15 = 661 kt (340 m/s)."}, {"q": "Le nombre de Mach est :", "o": ["CAS / vitesse du son", "Vitesse sol / vitesse du son", "IAS / 661", "TAS / vitesse du son"], "c": 3, "why": "M = vitesse vraie / vitesse du son locale."}, {"q": "Vitesse du son au FL350 en ISA (−54,3 °C) :", "o": ["661 kt", "593 kt", "576 kt", "600 kt"], "c": 2, "why": "38,94 × √218,85 = 576 kt."}, {"q": "Mach 0,82 au FL350 ISA : vitesse vraie ?", "o": ["542 kt", "472 kt", "492 kt", "820 kt"], "c": 1, "why": "0,82 × 576 = 472 kt."}, {"q": "Règle approchée sous FL100 : TAS ≈ CAS × (1 + 2 % par 1 000 ft). 200 kt CAS à 8 000 ft :", "o": ["232 kt", "200 kt", "216 kt", "320 kt"], "c": 0, "why": "8 × 2 % = 16 % : 200 × 1,16 = 232 kt."}, {"q": "En montée à vitesse indiquée constante, le Mach :", "o": ["Diminue", "Reste constant", "S'annule à la tropopause", "Augmente"], "c": 3, "why": "La TAS augmente et la vitesse du son baisse : le Mach monte. D'où la transition CAS → Mach en montée."}, {"q": "TAS 480 kt, vent de face 60 kt : vitesse sol ?", "o": ["540 kt", "480 kt", "420 kt", "360 kt"], "c": 2, "why": "GS = TAS − composante de face = 480 − 60 = 420 kt."}, {"q": "Mach 0,85 à −45 °C : vitesse vraie ?", "o": ["487 kt", "500 kt", "562 kt", "926 kt"], "c": 1, "why": "a = 38,94 × √228,15 = 588 kt ; TAS = 0,85 × 588 = 500 kt. Plus chaud = son plus rapide = plus de TAS à Mach égal."}, {"q": "Même Mach 0,85, l'air passe de −56,5 °C à −46,5 °C. La TAS :", "o": ["Augmente d'environ 11 kt", "Ne change pas", "Baisse d'environ 11 kt", "Augmente de 10 kt exactement"], "c": 0, "why": "TAS = 0,85 × (a₂ − a₁) = 0,85 × (586 − 573) ≈ +11 kt."}, {"q": "Mach 0,84 au FL380 ISA (−56,5 °C), vent arrière 35 kt, étape de 2 400 NM. Durée ?", "o": ["4 h 59", "5 h 23", "4 h 00", "4 h 39"], "c": 3, "why": "TAS = 0,84 × 573 = 481 kt ; GS = 516 kt ; t = 2 400 / 516 = 4,65 h."}]}, {"id": "L4", "t": "Formule 4 — Triangle des vitesses : dérive, cap, vitesse sol", "h": "<p>Le vent déplace la masse d'air : pour suivre une <b>route</b>, l'avion tient un <b>cap</b> corrigé de la dérive, et sa <b>vitesse sol</b> change.</p><div class=\"lf\">θ = direction du vent − route · sin(correction) = Vw × sin θ / TAS · cap = route + correction<br>GS = TAS × cos(correction) − Vw × cos θ · règle : dérive max ≈ 60 × Vw / TAS (degrés)</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>Route 270, TAS 440, vent 300/60 : θ = 30°, correction = asin(60 × 0,5 / 440) = <b>+3,9°</b>, cap <b>274°</b>, GS = 440 × 0,998 − 60 × 0,866 = <b>387 kt</b>.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Route 090, vent 090/40 (plein face) : correction nulle, GS = TAS − 40.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Règle rapide : vent de travers 30 kt, TAS 300 kt → dérive max ≈ <b>6°</b>.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"ofp\">OFP / log de navigation</button> <button type=\"button\" class=\"mini\" data-docopen=\"wintem\">Vents et températures</button> <button type=\"button\" class=\"mini\" data-docopen=\"route\">Carte de route</button></div>", "quiz": [{"q": "Le vent « 270/30 » vient :", "o": ["Vers l'ouest, 30 kt", "Du sud, 27 kt", "De l'ouest, 30 kt", "De l'est, 30 kt"], "c": 2, "why": "La direction donnée est celle d'où vient le vent."}, {"q": "Vent de travers venant de la droite : la dérive pousse l'avion vers :", "o": ["La droite ; on corrige à gauche", "La gauche ; on corrige le cap à droite", "L'avant", "Nulle part"], "c": 1, "why": "On met le nez « dans le vent » : cap = route + correction côté vent."}, {"q": "Dérive maximale approchée (règle Xmax = 60 × Vw / TAS) : vent 40 kt, TAS 400 kt :", "o": ["6°", "10°", "4°", "0,1°"], "c": 0, "why": "60 × 40 / 400 = 6°."}, {"q": "Route 090°, TAS 450 kt, vent 180/50. Correction de dérive ?", "o": ["−6,4° (cap ≈ 084°)", "0°", "50°", "6,4° (cap ≈ 096°)"], "c": 3, "why": "sin(correction) = 50 × sin(180 − 90) / 450 → 6,4° ; cap = 090 + 6,4 ≈ 096°."}, {"q": "Même cas : vitesse sol ?", "o": ["450 kt", "500 kt", "447 kt", "400 kt"], "c": 2, "why": "GS = 450 × cos(6,4°) − 50 × cos 90° = 447 kt : vent de travers pur, la GS baisse un peu."}, {"q": "Route 220°, TAS 480 kt, vent 300/80. Cap à tenir ?", "o": ["211°", "229°", "220°", "300°"], "c": 1, "why": "Angle vent/route 80° ; correction 9,4° ; cap = 229°."}, {"q": "Même cas : vitesse sol ?", "o": ["460 kt", "560 kt", "400 kt", "480 kt"], "c": 0, "why": "GS = 480 × cos(9,4°) − 80 × cos 80° = 460 kt."}, {"q": "Montée initiale : route 045°, TAS 250 kt, vent 020/60. Vitesse sol ?", "o": ["310 kt", "250 kt", "190 kt", "194 kt"], "c": 3, "why": "Vent à 25° de face à gauche : correction −5,8°, GS = 194 kt."}, {"q": "Route 160°, TAS 470 kt, vent 340/90 (plein arrière). Durée pour 1 200 NM ?", "o": ["2 h 33", "3 h 09", "2 h 09", "3 h 00"], "c": 2, "why": "Vent arrière pur : GS = 470 + 90 = 560 kt ; 1 200 / 560 = 2,14 h."}, {"q": "Aller-retour 900 NM sur un axe 000° / 180°, TAS 460 kt, vent 030/70. Temps total ?", "o": ["3,91 h", "3,99 h", "4,01 h", "4,62 h"], "c": 1, "why": "Aller GS 398 kt (2,26 h), retour GS 519 kt (1,73 h) : total 3,99 h. Le vent allonge toujours un aller-retour."}]}, {"id": "L5", "t": "Formule 5 — Temps, distance, consommation", "h": "<p>Trois grandeurs liées : <b>distance = vitesse sol × temps</b>, <b>carburant = consommation horaire × temps</b>, <b>distance spécifique = vitesse sol / consommation</b>. Elles remplissent l'OFP point par point.</p><div class=\"lf\">t = D / GS · D = GS × t · carburant = FF × t · distance spécifique = GS / FF (NM/kg) · heure prévue = heure + t</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>Étape 2 100 NM, GS 455 kt → t = <b>4 h 37</b> ; FF 5 400 kg/h → <b>24 930 kg</b>.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Point de report : prévu 12:42, passé 12:47 : retard de 5 min à reporter sur les ETA suivantes.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Contrôle carburant : prévu 31 200 kg au point, réel 30 600 kg → écart −600 kg, à surveiller (fuite ? vent ?).</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"ofp\">OFP / log de navigation</button> <button type=\"button\" class=\"mini\" data-docopen=\"fuel\">Bilan carburant</button> <button type=\"button\" class=\"mini\" data-docopen=\"fpl\">Plan de vol OACI</button></div>", "quiz": [{"q": "Distance 300 NM, vitesse sol 400 kt. Temps ?", "o": ["45 min", "1 h 20", "40 min", "1 h 33"], "c": 0, "why": "t = 300 / 400 = 0,75 h = 45 min."}, {"q": "Vitesse sol 420 kt pendant 1 h 30. Distance ?", "o": ["280 NM", "420 NM", "700 NM", "630 NM"], "c": 3, "why": "420 × 1,5 = 630 NM."}, {"q": "Consommation 2 400 kg/h pendant 2 h 15. Carburant ?", "o": ["4 800 kg", "5 040 kg", "5 400 kg", "2 415 kg"], "c": 2, "why": "2 400 × 2,25 = 5 400 kg."}, {"q": "Distance spécifique (NM par kg) à GS 450 kt et 2 500 kg/h :", "o": ["5,56 NM/kg", "0,18 NM/kg", "1,8 NM/kg", "0,018 NM/kg"], "c": 1, "why": "450 / 2 500 = 0,18 NM/kg."}, {"q": "1 850 NM à 460 kt de vitesse sol. Durée ?", "o": ["4 h 01", "4 h 00", "3 h 50", "4 h 40"], "c": 0, "why": "1 850 / 460 = 4,02 h."}, {"q": "Départ 21:40 UTC, 2 h 50 de vol. Arrivée UTC ?", "o": ["23:90 UTC", "00:30 UTC (même jour)", "23:30 UTC", "00:30 UTC (lendemain)"], "c": 3, "why": "21:40 + 2:50 = 24:30, soit 00:30 le lendemain."}, {"q": "Point de report à 312 NM, il reste 7 800 kg à 2 600 kg/h et GS 445 kt. Carburant restant au point ?", "o": ["7 747 kg", "5 200 kg", "5 977 kg", "6 398 kg"], "c": 2, "why": "t = 312 / 445 = 0,701 h ; consommé 1 823 kg ; reste 5 977 kg."}, {"q": "Prévu : 4 h 10 à 5 200 kg/h. Réel : vent de face, GS −8 %. Carburant supplémentaire ?", "o": ["0 kg", "≈ 1 880 kg", "≈ 1 730 kg", "≈ 416 kg"], "c": 1, "why": "Temps × 1/0,92 : 4,17 h → 4,53 h ; écart 0,36 h × 5 200 ≈ 1 880 kg."}, {"q": "Croisière 3 étapes : 420 NM à 450 kt, 380 NM à 470 kt, 510 NM à 430 kt. Temps total ?", "o": ["2 h 56", "2 h 50", "3 h 05", "2 h 40"], "c": 0, "why": "0,933 + 0,809 + 1,186 = 2,928 h."}, {"q": "Il reste 6 200 kg utilisables au-dessus de la réserve, distance spécifique 0,18 NM/kg. Distance encore franchissable ?", "o": ["34 444 NM", "620 NM", "112 NM", "1 116 NM"], "c": 3, "why": "6 200 × 0,18 = 1 116 NM."}]}, {"id": "L6", "t": "Formule 6 — Bilan carburant d'un avion de ligne", "h": "<p>Le carburant minimum de transport public (EASA <b>CAT.OP.MPA.181</b> et ses AMC) se construit terme par terme. Le commandant peut ajouter du <b>supplémentaire</b> (discretionary).</p><div class=\"lf\">Bloc = roulage + étape (trip) + route (≈ 5 % de l'étape, min. 5 min) + dégagement + réserve finale (30 min à 1 500 ft, turbine) + additionnel + supplémentaire<br>TOF = bloc − roulage · carburant à l'atterrissage prévu = TOF − étape</div><div class=\"lx\"><b>Exemple corrigé 1</b><br><b>Paris-CDG → La Réunion en A350-900</b> (≈ 9 400 km soit 5 075 NM, GS moyenne 485 kt, 5 800 kg/h [ESTIMÉ]) : étape ≈ 5 075 / 485 × 5 800 + montée/descente ≈ <b>62 200 kg</b> ; route 5 % = 3 110 ; dégagement Maurice 3 800 ; réserve finale 3 000 ; roulage 600 → bloc ≈ <b>72 700 kg</b>. Documents : bilan carburant, OFP, devis de masse (le carburant entre dans la masse), plan de vol OACI (autonomie case « E »).</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>A320 New York → Paris : étape 15 300, route 765, dégagement Orly 1 400, réserve finale 1 100, roulage 200 → <b>18 765 kg</b>.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Ajout d'un supplément de 1 500 kg pour orages prévus : bloc + 1 500 ; vérifier ensuite que la masse au décollage reste ≤ masse permise (formule 7).</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"fuel\">Bilan carburant</button> <button type=\"button\" class=\"mini\" data-docopen=\"ofp\">OFP / log de navigation</button> <button type=\"button\" class=\"mini\" data-docopen=\"loadsheet\">Devis de masse et centrage</button> <button type=\"button\" class=\"mini\" data-docopen=\"fpl\">Plan de vol OACI</button></div>", "quiz": [{"q": "La réserve finale d'un avion à turbine (EASA, transport public) vaut :", "o": ["10 % de l'étape", "45 min de croisière", "30 min d'attente à 1 500 ft au-dessus du dégagement", "1 h de vol"], "c": 2, "why": "CAT.OP.MPA.181 et AMC : 30 min à 1 500 ft (avions à turbine)."}, {"q": "Le carburant de route (contingency) usuel vaut :", "o": ["10 % du total", "5 % du carburant d'étape (avec un minimum)", "30 min", "Rien"], "c": 1, "why": "En général 5 % de l'étape, et au moins l'équivalent de 5 min d'attente (AMC1 CAT.OP.MPA.181)."}, {"q": "Ordre des termes du bilan :", "o": ["Roulage + étape + route + dégagement + réserve finale + additionnel + supplémentaire", "Étape + réserve seulement", "Dégagement + réserve finale", "Roulage + étape"], "c": 0, "why": "C'est l'ordre de l'OFP et du bilan carburant."}, {"q": "Roulage 200 kg, étape 6 000 kg, route 5 %, dégagement 1 500 kg, réserve finale 1 100 kg. Carburant minimum ?", "o": ["8 800 kg", "8 900 kg", "9 700 kg", "9 100 kg"], "c": 3, "why": "Route = 5 % × 6 000 = 300 kg ; total = 200 + 6 000 + 300 + 1 500 + 1 100 = 9 100 kg."}, {"q": "Carburant au décollage (TOF) avec ce bilan ?", "o": ["9 100 kg", "8 000 kg", "8 900 kg", "6 000 kg"], "c": 2, "why": "TOF = carburant au bloc − roulage."}, {"q": "Réserve finale : consommation en attente 2 400 kg/h. Combien ?", "o": ["2 400 kg", "1 200 kg", "600 kg", "720 kg"], "c": 1, "why": "30 min = 0,5 h : 2 400 × 0,5 = 1 200 kg."}, {"q": "Long-courrier : roulage 300, étape 18 400, route 5 %, dégagement 3 200, réserve finale 2 600, supplément commandant 1 000 kg. Bloc ?", "o": ["26 420 kg", "25 420 kg", "25 500 kg", "27 340 kg"], "c": 0, "why": "Route = 920 kg ; bloc = 26 420 kg."}, {"q": "Capacité réservoirs 20 000 kg, besoin calculé 21 400 kg. Que faire ?", "o": ["Partir quand même", "Supprimer la réserve finale", "Réduire le roulage", "Vol impossible tel quel : escale, dégagement plus proche ou charge réduite si c'est la masse qui limite"], "c": 3, "why": "Le minimum réglementaire ne se négocie pas : on change le plan (escale technique, dégagement plus proche)."}, {"q": "Bloc 13 990 kg (roulage 250, étape 9 800). Carburant prévu à l'atterrissage à destination ?", "o": ["4 190 kg", "1 350 kg", "3 940 kg", "3 450 kg"], "c": 2, "why": "Carburant à l'atterrissage = bloc − roulage − étape = 3 940 kg (= route + dégagement + réserve finale)."}, {"q": "En approche à destination avec ce plan, il reste 3 300 kg. Le seuil « minimum fuel » est dégagement + réserve finale = 3 450 kg. Que fait l'équipage ?", "o": ["Rien", "Déclare « MINIMUM FUEL » puis « MAYDAY FUEL » s'il risque d'atterrir sous la réserve finale", "Remise de gaz pour attendre", "Coupe un moteur"], "c": 1, "why": "CAT.OP.MPA.281 : « MINIMUM FUEL » quand toute attente supplémentaire ferait atterrir avec moins que la réserve prévue ; « MAYDAY, MAYDAY, MAYDAY, FUEL » si l'atterrissage se ferait sous la réserve finale."}]}, {"id": "L7", "t": "Formule 7 — Masses : ZFW, TOW, LW, masse permise, charge offerte", "h": "<p>Le <b>devis de masse</b> (loadsheet) vérifie trois limites certifiées : <b>MZFW</b>, <b>MTOW</b>, <b>MLW</b>. La masse au décollage permise est la plus petite des trois limites ramenées au décollage.</p><div class=\"lf\">ZFW = DOW + charge marchande · TOW = ZFW + TOF · LW = TOW − étape<br>TOW permise = min(MTOW, MZFW + TOF, MLW + étape) · charge offerte = TOW permise − TOW réelle (et ZFW ≤ MZFW)</div><div class=\"lx\"><b>Exemple corrigé 1</b><br><b>A350-900 Paris → La Réunion</b> : DOW 142,4 t [ESTIMÉ], 290 passagers × 84 = 24,4 t, bagages 4,4 t, fret 12 t → ZFW = <b>183,2 t</b> ≤ 195,7 ✓ ; TOF 72,1 t → TOW = <b>255,3 t</b> ≤ 283 ✓ ; LW = 255,3 − 62,2 = <b>193,1 t</b> ≤ 207 ✓.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Masses forfaitaires EASA : 84 kg par adulte (bagage à main compris) à partir de 30 sièges (CAT.POL.MAB.100).</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Si la MZFW limite, ajouter du carburant ne retire pas de charge ; si la MLW limite, réduire le carburant d'étape (dégagement plus proche) peut libérer de la charge.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"loadsheet\">Devis de masse et centrage</button> <button type=\"button\" class=\"mini\" data-docopen=\"notoc\">NOTOC et chargement</button> <button type=\"button\" class=\"mini\" data-docopen=\"fuel\">Bilan carburant</button></div>", "quiz": [{"q": "ZFW (masse sans carburant) =", "o": ["Masse de base en opération (DOW) + charge marchande", "DOW + carburant", "TOW − étape", "MTOW − carburant"], "c": 0, "why": "ZFW = DOW + passagers + bagages + fret."}, {"q": "TOW (masse au décollage) =", "o": ["ZFW + bloc", "DOW + TOF", "LW − étape", "ZFW + carburant au décollage (TOF)"], "c": 3, "why": "Le carburant de roulage est brûlé avant le décollage."}, {"q": "LW (masse à l'atterrissage) =", "o": ["TOW − TOF", "ZFW + étape", "TOW − carburant d'étape", "MLW"], "c": 2, "why": "On consomme le carburant d'étape en vol."}, {"q": "DOW 42 000 kg, 150 passagers à 84 kg, bagages 1 800 kg, fret 1 200 kg. ZFW ?", "o": ["54 600 kg", "57 600 kg", "56 250 kg", "56 400 kg"], "c": 1, "why": "150 × 84 = 12 600 ; ZFW = 42 000 + 12 600 + 1 800 + 1 200 = 57 600 kg."}, {"q": "ZFW 57 600 kg, TOF 9 400 kg. TOW ?", "o": ["67 000 kg", "66 800 kg", "57 600 kg", "48 200 kg"], "c": 0, "why": "57 600 + 9 400 = 67 000 kg."}, {"q": "TOW 67 000 kg, étape 6 900 kg. LW ?", "o": ["73 900 kg", "57 600 kg", "62 500 kg", "60 100 kg"], "c": 3, "why": "67 000 − 6 900 = 60 100 kg."}, {"q": "MTOW 78 000, MZFW 62 500, MLW 66 000 ; TOF 9 400, étape 6 900. Masse au décollage permise ?", "o": ["78 000 kg", "73 900 kg", "71 900 kg", "78 800 kg"], "c": 2, "why": "Le plus petit de : MTOW 78 000 ; MZFW + TOF = 71 900 ; MLW + étape = 72 900 → 71 900 kg."}, {"q": "Même vol, TOW réelle 67 000 kg. Charge offerte restante (underload) ?", "o": ["11 000 kg", "4 900 kg", "0 kg", "5 900 kg"], "c": 1, "why": "71 900 − 67 000 = 4 900 kg, mais vérifier aussi ZFW ≤ MZFW : 57 600 ≤ 62 500 ✓ (marge 4 900 kg) : la vraie marge est la plus petite."}, {"q": "A350-900 : MTOW 283 t, MZFW 195,7 t [ESTIMÉ], MLW 207 t [ESTIMÉ] ; TOF 70 t, étape 61 t. Masse permise et limite qui joue ?", "o": ["265,7 t, limitée par la MZFW", "283,0 t, limitée par la MTOW", "268,0 t, limitée par la MLW", "207,0 t"], "c": 0, "why": "MTOW 283 ; MZFW + TOF = 265,7 ; MLW + étape = 268,0 → 265,7 t (MZFW)."}, {"q": "Une LMC (modification de dernière minute) ajoute 6 passagers à 84 kg et retire 300 kg de fret. Effet sur la TOW ?", "o": ["+504 kg", "−204 kg", "+300 kg", "+204 kg"], "c": 3, "why": "6 × 84 − 300 = +204 kg, à reporter sur le devis de masse (case LMC) avant la signature."}]}, {"id": "L8", "t": "Formule 8 — Centrage : moments, CG, %MAC", "h": "<p>Le <b>centrage</b> est la position du centre de gravité. Trop avant : l'avion « tire » mal et consomme plus ; trop arrière : il devient instable. Le <b>trim de décollage</b> dépend du centrage.</p><div class=\"lf\">moment = masse × bras · CG = Σ moments / Σ masses · %MAC = (CG − LEMAC) / MAC × 100<br>déplacement d'une masse : ΔCG = m × d / M · masse à déplacer = ΔCG × M / d</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>Devis A350 du simulateur : moments par zone (cabine avant, cabine arrière, soutes) + carburant → %MAC affiché dans le devis de masse.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>300 kg de bagages chargés par erreur en soute arrière au lieu de l'avant (écart 20 m) sur 70 t : ΔCG = 300 × 20 / 70 000 = <b>8,6 cm</b> vers l'arrière.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Le trim (THS) se règle sur la valeur calculée depuis le %MAC au décollage : une erreur de centrage donne une rotation trop lourde ou trop vive.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"loadsheet\">Devis de masse et centrage</button> <button type=\"button\" class=\"mini\" data-docopen=\"notoc\">NOTOC et chargement</button></div>", "quiz": [{"q": "Moment d'une masse =", "o": ["Masse / bras", "Bras / masse", "Masse × bras de levier", "Masse + bras"], "c": 2, "why": "M = m × d (kg·m), le bras étant mesuré depuis la référence."}, {"q": "Centre de gravité =", "o": ["Somme des bras / nombre de masses", "Somme des moments / somme des masses", "Moment / bras", "Masse totale / moment"], "c": 1, "why": "CG = ΣM / Σm."}, {"q": "%MAC =", "o": ["(CG − LEMAC) / MAC × 100", "CG / MAC", "LEMAC / CG × 100", "(MAC − CG) × 100"], "c": 0, "why": "Le centrage s'exprime en pourcentage de la corde aérodynamique moyenne."}, {"q": "40 000 kg à 18 m, 10 000 kg à 22 m. CG ?", "o": ["20,0 m", "18,0 m", "19,5 m", "18,8 m"], "c": 3, "why": "(720 000 + 220 000) / 50 000 = 18,8 m."}, {"q": "CG 18,8 m, LEMAC 17,0 m, MAC 4,2 m. %MAC ?", "o": ["18,8 %", "447,6 %", "42,9 %", "7,6 %"], "c": 2, "why": "(18,8 − 17,0) / 4,2 × 100 = 42,9 %."}, {"q": "Masse totale 60 000 kg. On déplace 500 kg de 10 m vers l'arrière. Déplacement du CG ?", "o": ["10 m vers l'arrière", "8,3 cm vers l'arrière", "8,3 cm vers l'avant", "0,5 m"], "c": 1, "why": "ΔCG = m × d / M = 500 × 10 / 60 000 = 0,0833 m = 8,3 cm."}, {"q": "Masse 60 000 kg, il faut reculer le CG de 25 cm. Masse à transférer de la soute avant (bras 12 m) à la soute arrière (bras 24 m) ?", "o": ["1 250 kg", "625 kg", "417 kg", "2 500 kg"], "c": 0, "why": "m = ΔCG × M / d = 0,25 × 60 000 / (24 − 12) = 1 250 kg."}, {"q": "ZFW 180 t à 31,2 m ; on ajoute 70 t de carburant à 30,5 m. CG au décollage ?", "o": ["31,20 m", "30,50 m", "30,85 m", "31,00 m"], "c": 3, "why": "(180 000 × 31,2 + 70 000 × 30,5) / 250 000 = 31,00 m : moyenne pondérée, pas moyenne simple."}, {"q": "Ce CG (31,00 m), LEMAC 29,0 m, MAC 6,9 m [ESTIMÉ]. %MAC et conformité si limites 14 à 40 % ?", "o": ["29,0 % : hors limites", "449,3 % : hors limites", "29,0 % : dans les limites", "50 % : à la limite"], "c": 2, "why": "(31,00 − 29,0) / 6,9 × 100 = 29,0 %."}, {"q": "En vol, 61 t de carburant (bras 30,5 m) sont consommés. CG à l'atterrissage ?", "o": ["31,00 m", "31,17 m", "30,50 m", "30,87 m"], "c": 1, "why": "(250 000 × 31,00 − 61 000 × 30,5) / 189 000 = 31,17 m : le CG bouge avec la consommation, il faut le vérifier aussi à l'atterrissage."}]}, {"id": "L9", "t": "Formule 9 — Vent sur la piste : face, arrière, travers", "h": "<p>Avant chaque décollage et chaque atterrissage, le pilote décompose le vent selon l'axe de piste. La composante de face raccourcit les distances, la composante arrière les allonge (souvent limitée à 10 ou 15 kt), et le travers est limité par la valeur démontrée.</p><div class=\"lf\">θ = direction du vent − axe de piste · face (+) / arrière (−) = V × cos θ · travers = V × sin θ<br>repères : sin 30° = 0,5 · sin 45° ≈ 0,71 · sin 60° ≈ 0,87 · cos = sin du complément</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>Piste 26R (≈ 266°), vent 230/20 : θ = 36° → face 16 kt, travers <b>12 kt</b>.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Rafales : on fait le calcul avec la valeur de rafale pour le travers.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Piste 32 avec vent 140/12 : θ = 180° → <b>12 kt de vent arrière</b> : piste opposée, ou vérifier la limite.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"perf\">Performances (TODC)</button> <button type=\"button\" class=\"mini\" data-docopen=\"metar\">METAR / TAF</button> <button type=\"button\" class=\"mini\" data-docopen=\"app\">Carte d'approche</button></div>", "quiz": [{"q": "Composante de face d'un vent de V kt faisant un angle θ avec la piste :", "o": ["V × cos θ", "V × sin θ", "V × tan θ", "V / cos θ"], "c": 0, "why": "Face = V cos θ ; travers = V sin θ."}, {"q": "Composante de travers :", "o": ["V × cos θ", "V − θ", "V × θ / 60", "V × sin θ"], "c": 3, "why": "Elle se compare au vent traversier démontré de l'avion."}, {"q": "Vent dans l'axe de la piste (θ = 0) de 20 kt :", "o": ["Face 0, travers 20", "Face 10, travers 10", "Face 20 kt, travers 0", "Face 14, travers 14"], "c": 2, "why": "cos 0 = 1, sin 0 = 0."}, {"q": "Piste 27, vent 300/20. Face et travers ?", "o": ["Face 10 kt, travers 17 kt", "Face 17 kt, travers 10 kt", "Face 20 kt, travers 0", "Face 10 kt, travers 10 kt"], "c": 1, "why": "θ = 30° : face 20 × 0,87 = 17 ; travers 20 × 0,5 = 10 kt."}, {"q": "Piste 08, vent 140/25. Composante de travers ?", "o": ["22 kt", "13 kt", "25 kt", "12 kt"], "c": 0, "why": "θ = 60° : 25 × sin 60° = 22 kt."}, {"q": "Piste 26, vent 120/15. Que vaut la composante longitudinale ?", "o": ["11 kt de face", "15 kt de face", "0 kt", "11 kt de vent arrière"], "c": 3, "why": "θ = 140° : 15 × cos 140° = −11 kt : négatif = vent arrière ; souvent limité à 10 ou 15 kt."}, {"q": "La Réunion piste 14 (axe 136° vrai ≈ 140° pour le calcul), vent 120/30. Travers ?", "o": ["28 kt", "30 kt", "10 kt", "5 kt"], "c": 2, "why": "θ = 20° : 30 × sin 20° = 10 kt."}, {"q": "Piste 12, vent 070/35 rafales 50. Travers en rafale ?", "o": ["27 kt", "38 kt", "50 kt", "35 kt"], "c": 1, "why": "θ = 50° : 50 × sin 50° = 38 kt ; comparer à la limite de l'avion en tenant compte des rafales."}, {"q": "Vent 45 kt. Limite de vent traversier démontré 38 kt. Angle maximal vent/piste ?", "o": ["≈ 58°", "≈ 38°", "≈ 45°", "≈ 90°"], "c": 0, "why": "sin θ = 38 / 45 → θ ≈ 58°."}, {"q": "CDG : pistes 08/26 et 09/27. Vent 230/28. Quelle piste minimise le travers et donne du vent de face ?", "o": ["Piste 08", "Piste 09", "Indifférent", "Piste 26 (travers ≈ 14 kt)"], "c": 3, "why": "Axes 260° et 270° : travers 14 kt (26) et 18 kt (27) avec vent de face ; les pistes 08 et 09 auraient du vent arrière."}]}, {"id": "L10", "t": "Formule 10 — Performances de décollage et d'atterrissage", "h": "<p>Les vitesses (<b>V1, VR, V2, VAPP</b>) et les distances viennent des tableaux ou du logiciel de performances de l'exploitant. Le pilote doit comprendre leurs <b>tendances</b> et appliquer les <b>marges réglementaires</b>.</p><div class=\"lf\">distance ∝ masse² (approximation) · effet du vent : d ≈ d₀ × (1 ∓ Vw / V)² (face −, arrière +)<br>atterrissage, avion à réaction : distance démontrée ≤ 60 % de la LDA (sec) · mouillé : × 1,15 · VAPP ≈ VLS + 5 kt (plus une correction de vent)</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>A350 à 255 t (simulateur, formule pédagogique [ESTIMÉ]) : VR ≈ 149 kt, V1 ≈ 144, V2 ≈ 156.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Exemple chiffré (piste fictive de 2 600 m disponibles) : distance démontrée 1 450 m → 1 450 / 0,6 = 2 417 m ≤ 2 600 ✓ ; piste mouillée : 2 417 × 1,15 = 2 779 m ✗ → autre piste, masse plus faible ou attente.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Vent arrière 10 kt à 140 kt : d ≈ d₀ × (1 + 0,071)² = <b>+15 %</b>.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"perf\">Performances (TODC)</button> <button type=\"button\" class=\"mini\" data-docopen=\"loadsheet\">Devis de masse et centrage</button> <button type=\"button\" class=\"mini\" data-docopen=\"metar\">METAR / TAF</button></div>", "quiz": [{"q": "V1 est :", "o": ["La vitesse de rotation", "La vitesse de sécurité au décollage", "La vitesse de décision : après V1 on continue le décollage", "La vitesse d'approche"], "c": 2, "why": "Avant V1 on peut interrompre, après V1 on continue."}, {"q": "Ordre normal des vitesses :", "o": ["VR < V1 < V2", "V1 ≤ VR < V2", "V2 < V1 < VR", "V1 > V2"], "c": 1, "why": "V2 est la vitesse de sécurité au décollage atteinte à 35 ft."}, {"q": "Distance de décollage approximativement proportionnelle à :", "o": ["Le carré de la masse", "La masse", "La racine de la masse", "Indépendante de la masse"], "c": 0, "why": "Vitesse de rotation ∝ √m et accélération ∝ 1/m : distance ∝ m² (approximation)."}, {"q": "Masse +10 % : distance de décollage environ :", "o": ["+10 %", "+5 %", "+100 %", "+21 %"], "c": 3, "why": "1,1² = 1,21."}, {"q": "Atterrissage, avion à réaction, piste sèche (EASA) : la distance requise doit tenir dans :", "o": ["100 % de la LDA", "80 % de la LDA", "60 % de la distance disponible (LDA)", "50 % de la LDA"], "c": 2, "why": "CAT.POL.A.230 : distance d'atterrissage démontrée ≤ 60 % de la LDA (facteur 1,67)."}, {"q": "Piste mouillée : la distance requise sur sec est majorée de :", "o": ["5 %", "15 %", "50 %", "0 %"], "c": 1, "why": "CAT.POL.A.235 : 115 % de la distance requise sur piste sèche."}, {"q": "Distance démontrée sur piste sèche 1 500 m. LDA 2 800 m. Atterrissage possible sur piste sèche ?", "o": ["Oui : besoin 2 500 m ≤ 2 800 m", "Non : besoin 2 875 m", "Oui : besoin 1 500 m", "Non : besoin 3 000 m"], "c": 0, "why": "1 500 / 0,6 = 2 500 m."}, {"q": "Même cas sur piste mouillée ?", "o": ["Oui : besoin 2 875 m ≤ 2 800 m", "Oui : besoin 2 500 m", "Non : besoin 3 450 m", "Non : besoin 2 875 m > 2 800 m"], "c": 3, "why": "2 500 × 1,15 = 2 875 m, plus que les 2 800 m disponibles : piste plus longue, masse plus faible, ou attente que la piste sèche."}, {"q": "Distance de décollage sans vent 2 400 m, vitesse de décollage 150 kt. Avec 15 kt de vent de face (d ≈ d₀ × (1 − Vw/V)²) ?", "o": ["≈ 2 160 m", "≈ 2 400 m", "≈ 1 940 m", "≈ 2 900 m"], "c": 2, "why": "2 400 × (1 − 0,1)² = 2 400 × 0,81 = 1 944 m."}, {"q": "Distance de décollage 2 600 m à 240 t. Estimation à 255 t (même piste, même météo) ?", "o": ["≈ 2 763 m", "≈ 2 940 m", "≈ 2 600 m", "≈ 5 520 m"], "c": 1, "why": "2 600 × (255/240)² = 2 600 × 1,129 = 2 935 m : les performances réelles se lisent dans les tableaux ou le logiciel de l'exploitant."}]}, {"id": "L11", "t": "Formule 11 — Montée et descente : pente, taux, point de descente", "h": "<p>La <b>pente</b> (en % ou en degrés) relie le <b>taux vertical</b> à la <b>vitesse sol</b>. La gestion de la descente évite d'arriver trop haut, la première cause des approches non stabilisées.</p><div class=\"lf\">point de descente (NM) ≈ Δaltitude (milliers de ft) × 3 · taux sur 3° ≈ GS × 5 (ft/min)<br>pente (%) ≈ taux (ft/min) / GS (kt) · taux requis ≈ pente (%) × GS (kt) · plan de 3° ≈ 318 ft par NM</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>FL370 vers une arrivée à 3 000 ft : 34 × 3 = <b>102 NM</b> + 10 NM de décélération.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>ILS 14 à La Réunion, GS 140 kt : taux ≈ <b>700 ft/min</b>.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>SID à 3,3 % (pente standard) avec GS 160 kt : ≈ <b>535 ft/min</b> minimum.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"ofp\">OFP / log de navigation</button> <button type=\"button\" class=\"mini\" data-docopen=\"app\">Carte d'approche</button></div>", "quiz": [{"q": "Règle du point de descente (plan de 3°) :", "o": ["Distance (NM) ≈ altitude à perdre (en milliers de ft) × 3", "Distance = altitude × 10", "Distance = altitude / 3", "Distance = 100 NM"], "c": 0, "why": "Une pente de 3° perd ≈ 318 ft par NM, soit environ 1 000 ft tous les 3 NM."}, {"q": "Taux de descente sur un plan de 3° :", "o": ["Vitesse sol × 3", "TAS × 10", "700 ft/min toujours", "Vitesse sol (kt) × 5 (ft/min)"], "c": 3, "why": "Plus exactement GS × 5,3."}, {"q": "Perdre 33 000 ft : début de descente à environ :", "o": ["33 NM", "330 NM", "99 NM", "66 NM"], "c": 2, "why": "33 × 3 = 99 NM (plus quelques NM pour décélérer)."}, {"q": "Plan de 3° à 140 kt de vitesse sol : taux de descente ?", "o": ["≈ 420 ft/min", "≈ 700 ft/min", "≈ 1 400 ft/min", "≈ 140 ft/min"], "c": 1, "why": "140 × 5 = 700 ft/min."}, {"q": "Pente de montée (%) ≈ taux de montée (ft/min) / vitesse sol (kt) :", "o": ["≈ (taux / GS) %", "taux × GS", "GS / taux", "taux / 1 000"], "c": 0, "why": "1 kt ≈ 101 ft/min : pente (%) ≈ taux / GS (à 1 % près)."}, {"q": "Une SID exige 5 % de pente. Vitesse sol 180 kt : taux de montée minimal ?", "o": ["≈ 500 ft/min", "≈ 180 ft/min", "≈ 1 800 ft/min", "≈ 910 ft/min"], "c": 3, "why": "5 × 180 × 1,013 ≈ 912 ft/min."}, {"q": "Montée de 2 000 ft à 30 000 ft à 2 000 ft/min de moyenne et 380 kt de GS moyenne. Distance parcourue ?", "o": ["≈ 140 NM", "≈ 28 NM", "≈ 89 NM", "≈ 380 NM"], "c": 2, "why": "Durée 28 000 / 2 000 = 14 min ; distance 380 × 14 / 60 = 89 NM."}, {"q": "Contrainte : passer FL100 à 30 NM du seuil. On est au FL240 et à 80 NM. Pente faisable au plan de 3° ?", "o": ["Non, impossible", "Oui : il faut ≈ 42 NM et on en dispose de 50 (marge 8 NM)", "Il faut 24 NM", "Il faut 140 NM"], "c": 1, "why": "14 000 ft à perdre × 3 = 42 NM ; disponible 80 − 30 = 50 NM : marge 8 NM."}, {"q": "Descente FL350 → niveau de la mer à 2 500 ft/min, GS moyenne 300 kt. Distance nécessaire ?", "o": ["≈ 70 NM", "≈ 105 NM", "≈ 35 NM", "≈ 140 NM"], "c": 0, "why": "Durée 35 000 / 2 500 = 14 min ; 300 × 14 / 60 = 70 NM (plus raide que 3°)."}, {"q": "À 25 NM du seuil, l'avion est à 9 000 ft (seuil à 0 ft). Écart par rapport au plan de 3° (318 ft par NM) ?", "o": ["≈ 1 050 ft trop bas", "Sur le plan", "≈ 9 000 ft trop haut", "≈ 1 050 ft trop haut"], "c": 3, "why": "Sur le plan : 25 × 318 ≈ 7 950 ft ; 9 000 − 7 950 ≈ 1 050 ft trop haut : réduire la vitesse, aérofreins, ou demander des circuits supplémentaires."}]}, {"id": "L12", "t": "Formule 12 — Virage : facteur de charge, décrochage, rayon", "h": "<p>En virage, l'aile doit porter plus que le poids : le <b>facteur de charge</b> monte et la <b>vitesse de décrochage</b> aussi. Le <b>rayon</b> croît avec le carré de la vitesse.</p><div class=\"lf\">n = 1 / cos φ · Vs(φ) = Vs × √n · R = V² / (g × tan φ) (V en m/s) · inclinaison au taux standard ≈ TAS/10 + 7</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>Virage à 30° en approche à 160 kt : n = 1,15 ; si VLS = 130 kt, la marge réelle baisse à 160 vs 139 kt.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Attente à 230 kt et 25° : R ≈ 3 900 m ≈ 2,1 NM.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>60° d'inclinaison : n = 2, décrochage × 1,41 : manœuvre d'école, jamais avec passagers.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"app\">Carte d'approche</button></div>", "quiz": [{"q": "Facteur de charge en virage en palier :", "o": ["n = cos(inclinaison)", "n = tan(inclinaison)", "n = 1 / cos(inclinaison)", "n = 1"], "c": 2, "why": "La portance doit compenser le poids et fournir la force centripète."}, {"q": "n à 30° d'inclinaison :", "o": ["2,00", "1,15", "1,00", "1,41"], "c": 1, "why": "1 / cos 30° = 1,15."}, {"q": "n à 60° :", "o": ["2", "1,5", "1,15", "3"], "c": 0, "why": "1 / 0,5 = 2."}, {"q": "Vitesse de décrochage en virage :", "o": ["Vs × n", "Vs / n", "Vs", "Vs × √n"], "c": 3, "why": "Elle augmente comme la racine du facteur de charge."}, {"q": "Vs 120 kt en palier. À 45° d'inclinaison ?", "o": ["170 kt", "120 kt", "143 kt", "134 kt"], "c": 2, "why": "n = 1,414 ; 120 × √1,414 = 143 kt."}, {"q": "Inclinaison pour un virage au taux standard (3°/s) — règle :", "o": ["TAS / 2", "TAS / 10 + 7 (degrés)", "25° toujours", "TAS × 3"], "c": 1, "why": "Règle empirique ; souvent limitée à 25° par le pilote automatique."}, {"q": "TAS 140 kt : inclinaison au taux standard ?", "o": ["21°", "14°", "25°", "30°"], "c": 0, "why": "140 / 10 + 7 = 21°."}, {"q": "Rayon de virage à 250 kt TAS et 25° (R = V² / (g tan φ), V en m/s) ?", "o": ["≈ 1 810 m", "≈ 250 m", "≈ 1 690 m", "≈ 3 620 m"], "c": 3, "why": "V = 128,6 m/s ; R = 128,6² / (9,81 × 0,466) ≈ 3 615 m (2,0 NM)."}, {"q": "Même inclinaison à 450 kt : rayon ?", "o": ["≈ 2,0 NM", "≈ 1 NM", "≈ 6,3 NM", "≈ 12,6 NM"], "c": 2, "why": "Le rayon varie avec le carré de la vitesse : × (450/250)² = × 3,24 → ≈ 6,3 NM. D'où l'anticipation des virages en croisière."}, {"q": "Temps pour un tour complet à 250 kt et 25° ?", "o": ["2 min", "≈ 2,9 min", "1 min", "≈ 1,5 min"], "c": 1, "why": "Circonférence 2πR ≈ 22 715 m ; à 128,6 m/s → 177 s."}]}, {"id": "L13", "t": "Formule 13 — Point équitemps (PET) et point de non-retour (PNR)", "h": "<p>Sur les longs trajets (océan, désert), l'équipage calcule à l'avance où il vaut mieux revenir ou continuer en cas de problème (<b>PET</b>) et jusqu'où il peut encore revenir (<b>PNR</b>).</p><div class=\"lf\">PET : distance depuis le départ = D × H / (O + H) · temps = distance / O<br>PNR : temps = E × H / (O + H) (E : autonomie utilisable en heures) · distance = temps × O</div><div class=\"lx\"><b>Exemple corrigé 1</b><br>Océan, D 2 400 NM, O 460, H 520 : PET à 2 400 × 520 / 980 = <b>1 273 NM</b>.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Autonomie 7 h, O 470, H 430 : PNR à 7 × 430 / 900 = <b>3,34 h</b>, soit 1 570 NM.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>PET « un moteur » et PET « dépressurisation » : mêmes formules avec les vitesses (et altitudes) du cas de panne.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"ofp\">OFP / log de navigation</button> <button type=\"button\" class=\"mini\" data-docopen=\"route\">Carte de route</button> <button type=\"button\" class=\"mini\" data-docopen=\"fuel\">Bilan carburant</button></div>", "quiz": [{"q": "Point équitemps (PET) : c'est le point où :", "o": ["Le temps pour continuer = le temps pour revenir", "Le carburant est à moitié", "On est à mi-distance", "On ne peut plus revenir"], "c": 0, "why": "Utilisé pour décider en cas de panne ou de malade à bord."}, {"q": "Distance du PET depuis le départ :", "o": ["D / 2", "D × O / (O + H)", "D × (O + H)", "D × H / (O + H)"], "c": 3, "why": "O = vitesse sol aller (out), H = vitesse sol retour (home)."}, {"q": "Sans vent, le PET est :", "o": ["Au départ", "À l'arrivée", "À mi-distance", "Aux deux tiers"], "c": 2, "why": "O = H → D/2."}, {"q": "D = 2 000 NM, GS aller 420 kt, GS retour 500 kt. PET depuis le départ ?", "o": ["913 NM", "1 087 NM", "1 000 NM", "1 013 NM"], "c": 1, "why": "2 000 × 500 / 920 = 1 087 NM : avec vent de face à l'aller, le PET se rapproche de la destination."}, {"q": "Temps pour atteindre ce PET ?", "o": ["2,59 h", "2,17 h", "4,76 h", "2,00 h"], "c": 0, "why": "1 087 / 420 = 2,59 h."}, {"q": "Point de non-retour (PNR) : c'est :", "o": ["Le PET", "La moitié du carburant", "Le sommet de montée", "Le dernier point d'où l'on peut encore revenir au départ avec le carburant disponible (hors réserves)"], "c": 3, "why": "Au-delà, revenir est impossible : il faut continuer ou se dérouter en route."}, {"q": "Autonomie utilisable 6 h, GS aller 450 kt, GS retour 410 kt. Temps jusqu'au PNR (t = E × H / (O + H)) ?", "o": ["3,14 h", "3,00 h", "2,86 h", "3,30 h"], "c": 2, "why": "6 × 410 / 860 = 2,86 h."}, {"q": "Distance du PNR ?", "o": ["1 173 NM", "1 287 NM", "1 350 NM", "2 700 NM"], "c": 1, "why": "2,86 × 450 = 1 287 NM."}, {"q": "PET « un moteur » : D 1 800 NM, GS un moteur vers la destination 380 kt, vers le départ 430 kt [ESTIMÉ]. PET ?", "o": ["956 NM", "844 NM", "900 NM", "851 NM"], "c": 0, "why": "On prend les vitesses du cas étudié (un moteur) : 1 800 × 430 / 810 = 956 NM."}, {"q": "Paris → La Réunion de nuit, malade grave à bord à 1 h 30 avant le PET calculé vers Addis-Abeba / Nairobi. Que fait l'équipage ?", "o": ["Il continue toujours vers la destination", "Il revient toujours au départ", "Il attend le PET", "Il compare le temps vers les terrains possibles (avant le PET, revenir ou dérouter est plus court) et se déroute vers le plus adapté, médicalement et techniquement"], "c": 3, "why": "Le PET aide à décider vite : avant lui, le terrain derrière est plus près en temps ; après, celui devant. On tient compte aussi du terrain (piste, secours, médecins) et de la météo."}]}, {"id": "L14", "t": "Formule 14 — Heures UTC, heures locales, fuseaux", "h": "<p>Toute la préparation se fait en <b>UTC</b> (plan de vol, OFP, METAR, NOTAM). Les passagers et les horaires commerciaux utilisent l'<b>heure locale</b>.</p><div class=\"lf\">heure UTC = heure locale − décalage · heure locale = UTC + décalage<br>Paris UTC +1 (hiver) / +2 (été) · La Réunion UTC +4 · New York UTC −5 (hiver) / −4 (été)</div><div class=\"lx\"><b>Exemple corrigé 1</b><br><b>AF652 Paris → La Réunion</b> : 18:00 Paris = 17:00 UTC ; + 11 h 00 = 04:00 UTC = <b>08:00 à La Réunion</b>.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br>Le METAR « 160600Z » est l'observation du 16 à 06:00 UTC, soit 07:00 à Paris en hiver.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br>Retour La Réunion 21:00 locale = 17:00 UTC ; + 11 h 30 = 04:30 UTC = 05:30 à Paris en hiver.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"fpl\">Plan de vol OACI</button> <button type=\"button\" class=\"mini\" data-docopen=\"ofp\">OFP / log de navigation</button> <button type=\"button\" class=\"mini\" data-docopen=\"metar\">METAR / TAF</button></div>", "quiz": [{"q": "En aviation, les heures des plans de vol et des messages sont en :", "o": ["Heure locale du départ", "Heure locale de l'arrivée", "UTC", "Heure de Paris"], "c": 2, "why": "Le temps universel coordonné évite les confusions de fuseau."}, {"q": "Paris en hiver est à :", "o": ["UTC +2", "UTC +1", "UTC", "UTC −1"], "c": 1, "why": "Heure d'été : UTC +2."}, {"q": "La Réunion est à :", "o": ["UTC +4 (pas d'heure d'été)", "UTC +3", "UTC +2", "UTC −4"], "c": 0, "why": "Fuseau Indian/Reunion."}, {"q": "New York en hiver est à :", "o": ["UTC −4", "UTC +5", "UTC −6", "UTC −5"], "c": 3, "why": "UTC −4 en été."}, {"q": "Départ CDG 18:00 heure de Paris en novembre. En UTC ?", "o": ["19:00 UTC", "16:00 UTC", "17:00 UTC", "18:00 UTC"], "c": 2, "why": "Paris = UTC +1 en novembre : 18:00 − 1 h = 17:00 UTC."}, {"q": "Vol de 11 h 00. Arrivée UTC ?", "o": ["05:00 UTC", "04:00 UTC (lendemain)", "04:00 UTC (même jour)", "03:00 UTC"], "c": 1, "why": "17:00 + 11:00 = 28:00 → 04:00 le lendemain."}, {"q": "Heure locale à La Réunion ?", "o": ["08:00", "07:00", "05:00", "04:00"], "c": 0, "why": "UTC +4 : 04:00 + 4 h = 08:00, comme l'horaire AF652."}, {"q": "JFK 18:30 heure locale (hiver), 7 h 20 de vol. Arrivée heure de Paris ?", "o": ["01:50", "06:50", "08:50", "07:50"], "c": 3, "why": "18:30 + 5 h = 23:30 UTC ; + 7:20 = 06:50 UTC ; Paris UTC +1 → 07:50."}, {"q": "Décalage horaire subi par les passagers Paris (hiver) → La Réunion :", "o": ["+4 h", "+1 h", "+3 h", "−3 h"], "c": 2, "why": "UTC +4 − (UTC +1) = 3 h."}, {"q": "L'équipage se présente à 05:15 UTC pour un départ bloc à 06:00 UTC ; vol de 11 h 10 bloc à bloc. Durée du temps de service de vol (de la présentation à l'arrivée au bloc) ?", "o": ["11 h 55", "11 h 10", "12 h 25", "11 h 40"], "c": 0, "why": "Arrivée au bloc 06:00 + 11:10 = 17:10 UTC ; 05:15 → 17:10 = 11 h 55. Le temps de service de vol (FDP, règlement ORO.FTL) s'arrête à l'arrivée au bloc ; les 30 min de fin de service comptent dans le temps de service total, pas dans le FDP."}]}, {"id": "L15", "t": "Cas complet — Paris-CDG → La Réunion en A350-900 : quel carburant, quels documents ?", "h": "<p>Mise en pratique de toutes les formules sur le vol long-courrier du simulateur. Valeurs de l'avion : masse maximale au décollage 283 t et capacité 141 000 l [RÉFÉRENCÉ Airbus] ; consommation, masses de base et vitesses [ESTIMÉ].</p><div class=\"lf\">étape ≈ (D / GS + 0,25 h) × FF = (5 075 / 485 + 0,25) × 5 800 ≈ 62 100 kg · bloc = roulage + étape + 5 % + dégagement + 30 min = 72 600 kg</div><div class=\"lx\"><b>Exemple corrigé 1</b><br><b>Carburant</b> : roulage 600 + étape 62 100 + route 3 100 + dégagement Maurice 3 800 + réserve finale 3 000 = <b>72 600 kg</b> (≈ 92 484 l). → <i>Bilan carburant</i> et <i>OFP</i>.</div><div class=\"lx\"><b>Exemple corrigé 2</b><br><b>Masses</b> : ZFW 183 200 kg → TOW 255 200 kg (≤ 283 t), LW 193 100 kg (≤ 207 t [ESTIMÉ]). → <i>Devis de masse et centrage</i>.</div><div class=\"lx\"><b>Exemple corrigé 3</b><br><b>Performances et plan de vol</b> : vitesses de décollage depuis la TOW, vent sur la piste 26R ; autonomie (case E du plan de vol OACI) = TOF / consommation. → <i>Performances</i>, <i>Plan de vol OACI</i>. Ouvrez l'écran « 🧮 Calculs du vol » pour refaire tout le calcul avec les données de votre mission.</div><div class=\"ld\"><b>📄 Documents à remplir avec ce calcul :</b> <button type=\"button\" class=\"mini\" data-docopen=\"fuel\">Bilan carburant</button> <button type=\"button\" class=\"mini\" data-docopen=\"ofp\">OFP / log de navigation</button> <button type=\"button\" class=\"mini\" data-docopen=\"loadsheet\">Devis de masse et centrage</button> <button type=\"button\" class=\"mini\" data-docopen=\"perf\">Performances (TODC)</button> <button type=\"button\" class=\"mini\" data-docopen=\"fpl\">Plan de vol OACI</button> <button type=\"button\" class=\"mini\" data-docopen=\"plan\">Plan de vol (check-list)</button></div>", "quiz": [{"q": "Premier calcul de la préparation carburant :", "o": ["La réserve finale", "Le roulage", "Le supplément", "Le carburant d'étape (distance, vents, niveau, masse)"], "c": 3, "why": "Tout le bilan part de l'étape."}, {"q": "Route ≈ 5 075 NM, vitesse sol moyenne 485 kt. Temps de vol (croisière) ?", "o": ["10,15 h", "9,00 h", "10,46 h", "19,38 h"], "c": 2, "why": "5 075 / 485 = 10,46 h."}, {"q": "Consommation moyenne 5 800 kg/h [ESTIMÉ], + 15 min pour montée et approche. Carburant d'étape (arrondi à 100 kg) ?", "o": ["60 700 kg", "62 100 kg", "65 205 kg", "58 000 kg"], "c": 1, "why": "(10,46 + 0,25) × 5 800 ≈ 62 100 kg."}, {"q": "Carburant de route (5 %) ?", "o": ["3 100 kg", "3 000 kg", "6 200 kg", "600 kg"], "c": 0, "why": "5 % × 62 100 ≈ 3 100 kg."}, {"q": "Dégagement de La Réunion utilisé dans le simulateur :", "o": ["Mayotte (FMCZ)", "Paris-Orly", "Nairobi", "Maurice (FIMP)"], "c": 3, "why": "Le dossier de vol du simulateur prévoit Maurice (Sir Seewoosagur Ramgoolam)."}, {"q": "Bloc minimum avec dégagement 3 800, réserve finale 3 000, roulage 600 kg ?", "o": ["69 500 kg", "68 800 kg", "72 600 kg", "75 600 kg"], "c": 2, "why": "600 + 62 100 + 3 100 + 3 800 + 3 000 = 72 600 kg."}, {"q": "Ce bloc en litres de JET A-1 à 0,785 kg/l ?", "o": ["56 991 l", "92 484 l", "72 600 l", "71 239 l"], "c": 1, "why": "72 600 / 0,785 = 92 484 l, sous la capacité de 141 000 l [RÉFÉRENCÉ Airbus]."}, {"q": "ZFW 183 200 kg. TOW ?", "o": ["255 200 kg", "255 800 kg", "245 300 kg", "283 000 kg"], "c": 0, "why": "TOW = ZFW + (bloc − roulage) = 183 200 + 72 000 = 255 200 kg ≤ 283 000 ✓."}, {"q": "LW prévue à La Réunion ?", "o": ["255 200 kg", "183 200 kg", "182 600 kg", "193 100 kg"], "c": 3, "why": "255 200 − 62 100 = 193 100 kg ≤ 207 000 [ESTIMÉ] ✓."}, {"q": "Quels documents remplit-on avec ces résultats, dans l'ordre ?", "o": ["Seulement le plan de vol", "Le compte rendu matériel", "Bilan carburant → OFP → devis de masse et centrage → performances → plan de vol OACI (autonomie)", "Le manifeste puis rien"], "c": 2, "why": "Chaque document reprend le résultat du précédent : le carburant entre dans la masse, la masse dans les performances, l'autonomie dans le plan de vol."}]}];
ACAD.setPart({id:'p9',n:'Partie 9 — Calculs du pilote de ligne',d:'14 formules du pilote de ligne (unités, atmosphère, vitesses et Mach, vent, temps et carburant, bilan carburant, masses, centrage, vent sur la piste, performances, montée et descente, virage, PET et PNR, heures UTC) et un cas complet Paris → La Réunion : cours, 3 exemples corrigés, 10 questions par formule, documents à remplir.',mods:MODS});
if(typeof QB!=='undefined'){ QB.calcpro=MODS.flatMap(m=>m.quiz.map(x=>[x.q,x.o,x.c,x.why])); if(typeof QTH!=='undefined'&&!QTH.find(x=>x[0]==='calcpro')) QTH.push(['calcpro','Calculs du pilote de ligne (150 questions)']); }
// boutons « Documents à remplir » : ouvrent le document du dossier de vol
document.addEventListener('click',e=>{ const b=e.target.closest&&e.target.closest('[data-docopen]'); if(!b) return; try{ DOCS.open(b.dataset.docopen); }catch(er){ console.warn('document',er); } });
})();
